// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

/**
 * Learned-selectivity pattern keys for {@code ?s ?p <const>}: a variable predicate combined with a constant object must
 * produce a stable key instead of failing, and must stay distinct from the constant-predicate cell.
 */
class PatternKeysVariablePredicateTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI B = VF.createIRI("urn:b");
	private static final IRI C = VF.createIRI("urn:c");

	@Test
	void variablePredicateWithConstantObjectYieldsStableKey() {
		PatternKey key = FilterSelectivityKeys.patternKeyFor(pattern(null, B));

		assertNotNull(key);
		assertNotNull(key.predicate(), "the constant object must stay part of the learned cell identity");
		assertEquals(PatternKey.OBJECT_BOUND, key.boundMask());
		assertEquals(key, FilterSelectivityKeys.patternKeyFor(pattern(null, B)));
		assertEquals(key.hashCode(), FilterSelectivityKeys.patternKeyFor(pattern(null, B)).hashCode());
		assertNotEquals(key, FilterSelectivityKeys.patternKeyFor(pattern(null, C)),
				"different constant objects must not share a learned cell");
	}

	@Test
	void variablePredicateCellDiffersFromConstantPredicateCell() {
		PatternKey variable = FilterSelectivityKeys.patternKeyFor(pattern(null, B));
		PatternKey constant = FilterSelectivityKeys.patternKeyFor(pattern(P, B));

		assertEquals(PatternKey.PREDICATE_BOUND | PatternKey.OBJECT_BOUND, constant.boundMask());
		assertNotEquals(variable, constant);
		assertNotEquals(variable.predicate(), constant.predicate(), "keys must differ, not only the bound mask");
	}

	@Test
	void constantPredicateKeysStayByteIdentical() {
		String encoded = Base64.getUrlEncoder()
				.withoutPadding()
				.encodeToString(("urn:p\u0000urn:b").getBytes(StandardCharsets.UTF_8));

		assertEquals(VF.createIRI("urn:rdf4j:learned:constantObject:" + encoded), PatternKeys.predicateKey(P, B),
				"persisted learned cells for constant predicates must keep matching");
		assertEquals(P, PatternKeys.predicateKey(P, null));
		assertNull(PatternKeys.predicateKey(null, null));
	}

	@Test
	void fullyVariablePatternKeepsNullPredicate() {
		PatternKey key = FilterSelectivityKeys.patternKeyFor(new StatementPattern(Var.of("s"), Var.of("p"),
				Var.of("o")));

		assertNull(key.predicate());
		assertEquals(0, key.boundMask());
	}

	private static StatementPattern pattern(IRI predicate, IRI object) {
		Var predicateVar = predicate == null ? Var.of("p") : Var.of("_const_p", predicate, true, true);
		return new StatementPattern(Var.of("s"), predicateVar, Var.of("_const_o", object, true, true));
	}
}
